const kbItems = $input.all();
const query = ($('Search Webhook').first().json.body?.query || $('Search Webhook').first().json.query || '').toLowerCase();

if (!query) {
  return { json: { results: [], message: 'No search query provided' } };
}

// Simple keyword matching
const results = kbItems
  .map(item => {
    const question = (item.json.Question || item.json.fields?.Question || '').toLowerCase();
    const answer = (item.json.Answer || item.json.fields?.Answer || '').toLowerCase();
    const title = (item.json['Article Title'] || item.json.fields?.['Article Title'] || '').toLowerCase();
    const category = item.json['FAQ Category'] || item.json.fields?.['FAQ Category'] || '';

    // Calculate relevance score
    let score = 0;
    const queryWords = query.split(' ');

    for (const word of queryWords) {
      if (word.length < 3) continue;
      if (question.includes(word)) score += 3;
      if (title.includes(word)) score += 2;
      if (answer.includes(word)) score += 1;
    }

    return {
      question: item.json.Question || item.json.fields?.Question,
      answer: item.json.Answer || item.json.fields?.Answer,
      category,
      score
    };
  })
  .filter(item => item.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

return {
  json: {
    query,
    results,
    count: results.length
  }
};
